-- Create enums for validation portal
DO $$ BEGIN
  CREATE TYPE validation_session_status AS ENUM ('active', 'closed');
EXCEPTION WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
  CREATE TYPE validation_assignment_status AS ENUM ('in_progress', 'completed');
EXCEPTION WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
  CREATE TYPE validation_verdict AS ENUM ('correct', 'incorrect');
EXCEPTION WHEN duplicate_object THEN null;
END $$;

-- Create validation_sessions table
CREATE TABLE IF NOT EXISTS validation_sessions (
  id SERIAL PRIMARY KEY,
  "projectId" INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title VARCHAR(255) NOT NULL,
  "shareToken" VARCHAR(64) NOT NULL UNIQUE,
  "totalDocs" INTEGER NOT NULL DEFAULT 0,
  "reviewsPerDoc" INTEGER NOT NULL DEFAULT 5,
  status validation_session_status NOT NULL DEFAULT 'active',
  "documentIds" JSONB NOT NULL,
  "createdAt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "closedAt" TIMESTAMP
);

CREATE INDEX IF NOT EXISTS vs_projectId_idx ON validation_sessions("projectId");
CREATE INDEX IF NOT EXISTS vs_shareToken_idx ON validation_sessions("shareToken");

-- Create validation_assignments table
CREATE TABLE IF NOT EXISTS validation_assignments (
  id SERIAL PRIMARY KEY,
  "sessionId" INTEGER NOT NULL REFERENCES validation_sessions(id) ON DELETE CASCADE,
  "documentId" INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  "reviewerUsername" VARCHAR(100) NOT NULL,
  status validation_assignment_status NOT NULL DEFAULT 'in_progress',
  "totalLines" INTEGER NOT NULL DEFAULT 0,
  "linesReviewed" INTEGER NOT NULL DEFAULT 0,
  "correctCount" INTEGER NOT NULL DEFAULT 0,
  "incorrectCount" INTEGER NOT NULL DEFAULT 0,
  "assignedAt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "completedAt" TIMESTAMP
);

CREATE INDEX IF NOT EXISTS va_sessionId_idx ON validation_assignments("sessionId");
CREATE INDEX IF NOT EXISTS va_documentId_idx ON validation_assignments("documentId");
CREATE INDEX IF NOT EXISTS va_reviewer_idx ON validation_assignments("reviewerUsername");
CREATE INDEX IF NOT EXISTS va_session_doc_reviewer_idx ON validation_assignments("sessionId", "documentId", "reviewerUsername");

-- Create validation_reviews table
CREATE TABLE IF NOT EXISTS validation_reviews (
  id SERIAL PRIMARY KEY,
  "assignmentId" INTEGER NOT NULL REFERENCES validation_assignments(id) ON DELETE CASCADE,
  "sessionId" INTEGER NOT NULL REFERENCES validation_sessions(id) ON DELETE CASCADE,
  "documentId" INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  "reviewerUsername" VARCHAR(100) NOT NULL,
  "lineIndex" INTEGER NOT NULL,
  "lineText" TEXT NOT NULL,
  verdict validation_verdict NOT NULL,
  "createdAt" TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS vr_assignmentId_idx ON validation_reviews("assignmentId");
CREATE INDEX IF NOT EXISTS vr_sessionId_idx ON validation_reviews("sessionId");
CREATE INDEX IF NOT EXISTS vr_documentId_idx ON validation_reviews("documentId");
CREATE INDEX IF NOT EXISTS vr_session_doc_line_idx ON validation_reviews("sessionId", "documentId", "lineIndex");

